/*
 * IS THIS A LEARNER WE CAN ADD? (TASK-L184 §1) — checked BEFORE anything is
 * written, so a malformed address or a blank project creates no account.
 *
 * The address is the identity: trimmed and lower-cased, because the magic link
 * finds an account by the address typed into the sign-in form and two spellings
 * of one address would be two people. It becomes the account's USERNAME as
 * well as its email, which is what NodeGX's Create User keys on — so a second
 * press with the same address finds the account rather than making another.
 *
 * Each refusal is its own sentence, so the coach can act on it; none of them
 * says whether an account exists for some other address.
 */
if (Inputs.email !== undefined && Inputs.projectName !== undefined) {
  const email = String(Inputs.email || '').trim().toLowerCase();
  const projectName = String(Inputs.projectName || '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) {
    Outputs.why = 'That does not look like an email address. Check it and try again.';
    Outputs.refuse();
  } else if (!projectName) {
    Outputs.why = 'Give their project a name. It can be a working title; you can change it later.';
    Outputs.refuse();
  } else {
    Outputs.email = email;
    Outputs.go();
  }
}

/*
 * GIVE THE ACCOUNT A LEARNER, A PROJECT AND THE COACH'S LABEL (TASK-L184 §1).
 *
 * By here the account exists: Create User made it, or found it (Unchanged) —
 * either way `userId` is the account behind this address. `roles` is that
 * account's roles, read fresh.
 *
 * A STAFF ADDRESS IS REFUSED. A coach's account is not a learner, and giving it
 * a learner profile would put a coach on their own roster. Create User never
 * makes a staff account (privilege comes only from a role), so a staff address
 * always arrives here as an EXISTING account and nothing has been written.
 *
 * IDEMPOTENT, AND IN THIS ORDER so a crash is healed by pressing again:
 *   1. the account   (Create User — "already exists" hands back its id)
 *   2. the profile   (found by the account, or made with a new learner id)
 *   3. the project   (found by the learner, or made at version 1, empty facts)
 *   4. the label     (a claimed invite carrying the coach's private shorthand,
 *                     only if a label was given and none is held yet)
 * Each step looks before it writes and fills only what is missing, so a second
 * press with the same address writes nothing, and never makes a second learner
 * behind one address (`Caller learner` refuses two profiles, rightly).
 *
 * THE LABEL IS THE COACH'S PRIVATE SHORTHAND (the product's L84). It lives on
 * `LearnerInvite.label`, where the roster reads it, and no learner function
 * reads that collection. Nothing here derives a name from the address (L106).
 */
if (Inputs.userId !== undefined && Inputs.roles !== undefined && Inputs.projectName !== undefined) {
  (async () => {
    /* THE COACH WHO ADDED THEM (TASK-L188 §1): the caller's own address, read from
       the session's account, recorded on a NEW profile only. An existing profile
       is never re-pointed by a second add, and nothing is back-filled from a guess
       (the product's L132): with no coach recorded, a question goes to every staff
       account and says so. */
    const callers = Inputs.callerId ? await Noodl.Records.query('_User', { objectId: { equalTo: String(Inputs.callerId) } }, { limit: 2, plain: true }) : [];
    const coachEmail = callers.length === 1 && typeof callers[0].username === 'string' ? callers[0].username.trim().toLowerCase() : null;
    const R = Noodl.Records;
    const q = (c, where, limit) => R.query(c, where, { limit: limit || 2, plain: true });
    try {
      const userId = String(Inputs.userId || '');
      if (!userId) throw new Error('no account');
      const roles = Array.isArray(Inputs.roles) ? Inputs.roles.map((r) => (r && r.name) || r) : [];
      if (roles.indexOf('staff') !== -1) {
        Outputs.why = 'That address belongs to a coach on this site, so it cannot be added as a learner.';
        Outputs.refuse();
        return;
      }
      const projectName = String(Inputs.projectName || '').trim();
      const problemStatement = String(Inputs.problemStatement || '').trim();
      const label = String(Inputs.label || '').trim();

      let created = false;
      const profiles = await q('LearnerProfile', { userId: { equalTo: userId } });
      if (profiles.length > 1) throw new Error('two learner profiles for one account');
      let learnerId = profiles.length ? profiles[0].learnerId : '';
      if (!learnerId) {
        learnerId = 'l-' + (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now()) + Math.random().toString(16).slice(2));
        await R.create('LearnerProfile', { learnerId, userId, coachEmail: coachEmail });
        created = true;
      }

      const contexts = await q('ProjectContext', { learnerId: { equalTo: learnerId } });
      if (!contexts.length) {
        await R.create('ProjectContext', { learnerId, projectName, problemStatement, facts: {}, version: 1 });
        created = true;
      }

      if (label) {
        const invites = await q('LearnerInvite', { claimedByLearnerId: { equalTo: learnerId } });
        if (!invites.length) {
          const me = Noodl.Users && Noodl.Users.Current;
          const coach = me && me.Properties && typeof me.Properties.get === 'function' ? me.Properties.get('email') : null;
          const now = new Date().toISOString();
          await R.create('LearnerInvite', {
            inviteId: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : 'inv-' + Date.now(),
            label,
            claimedByLearnerId: learnerId,
            claimedAt: now,
            status: 'claimed',
            createdByEmail: coach || null
          });
          created = true;
        }
      }

      console.log('[dbt:addLearner] ' + (created ? 'added' : 'already there') + ' learner=' + learnerId);
      Outputs.learnerId = learnerId;
      Outputs.created = created;
      Outputs.done();
    } catch (e) {
      Outputs.why = 'That did not finish. Nothing you typed is lost; press Add again.';
      console.error('[dbt:addLearner] stopped: ' + String((e && e.message) || e));
      Outputs.refuse();
    }
  })();
}
